long long maxSum(vector<int>& nums, int m, int k) {
    long long ans = 0;
    for (int i = 0; i + k <= (int)nums.size(); i++) {
        unordered_set<int> st(nums.begin() + i, nums.begin() + i + k);
        if ((int)st.size() >= m) {
            long long s = 0;
            for (int j = i; j < i + k; j++) s += nums[j];
            ans = max(ans, s);
        }
    }
    return ans;
}

