class Solution:
    def maxSum(self, nums: List[int], m: int, k: int) -> int:
        from collections import Counter
        cnt = Counter(nums[:k])
        s = sum(nums[:k])
        ans = s if len(cnt) >= m else 0
        for i in range(k, len(nums)):
            out = nums[i - k]
            cnt[out] -= 1
            if cnt[out] == 0:
                del cnt[out]
            cnt[nums[i]] += 1
            s += nums[i] - out
            if len(cnt) >= m:
                ans = max(ans, s)
        return ans

