long long maxSum(vector<int>& nums, int m, int k) {
    unordered_map<int, int> cnt;
    long long s = 0;
    for (int i = 0; i < k; i++) { cnt[nums[i]]++; s += nums[i]; }
    long long ans = (int)cnt.size() >= m ? s : 0;
    for (int i = k; i < (int)nums.size(); i++) {
        int out = nums[i - k];
        if (--cnt[out] == 0) cnt.erase(out);
        cnt[nums[i]]++;
        s += nums[i] - out;
        if ((int)cnt.size() >= m) ans = max(ans, s);
    }
    return ans;
}

