public long maxSum(List<Integer> nums, int m, int k) {
    Map<Integer, Integer> cnt = new HashMap<>();
    long s = 0;
    for (int i = 0; i < k; i++) { cnt.merge(nums.get(i), 1, Integer::sum); s += nums.get(i); }
    long ans = cnt.size() >= m ? s : 0;
    for (int i = k; i < nums.size(); i++) {
        int out = nums.get(i - k);
        cnt.merge(out, -1, Integer::sum);
        if (cnt.get(out) == 0) cnt.remove(out);
        cnt.merge(nums.get(i), 1, Integer::sum);
        s += nums.get(i) - out;
        if (cnt.size() >= m) ans = Math.max(ans, s);
    }
    return ans;
}

