    const cnt = new Map();
    let s = 0;
    for (let i = 0; i < k; i++) { cnt.set(nums[i], (cnt.get(nums[i]) || 0) + 1); s += nums[i]; }
    let ans = cnt.size >= m ? s : 0;
    for (let i = k; i < nums.length; i++) {
        const out = nums[i - k];
        cnt.set(out, cnt.get(out) - 1);
        if (cnt.get(out) === 0) cnt.delete(out);
        cnt.set(nums[i], (cnt.get(nums[i]) || 0) + 1);
        s += nums[i] - out;
        if (cnt.size >= m) ans = Math.max(ans, s);
    }
    return ans;
};
